/**
 * Environment contract of the gateway.
 *
 * Binding types are generated by `wrangler types` into `worker-configuration.d.ts`.
 * Internal services are reachable only through Service Bindings — there are no
 * direct HTTP hops between services in this project.
 */
import type { AuthenticatedUser } from '@notio/contracts';
import type { GatewayConfig } from './config';

export interface Bindings {
  PAGES_SERVICE: Fetcher;
  AUTH_SERVICE: Fetcher;
  WORKSPACE_SERVICE: Fetcher;
  MEDIA_SERVICE: Fetcher;
  RATE_LIMIT: KVNamespace;
  ENVIRONMENT: string;
  SERVICE_VERSION: string;
  LOG_LEVEL: string;
  CORS_ALLOWED_ORIGINS: string;
  RATE_LIMIT_MAX_REQUESTS: string;
  RATE_LIMIT_WINDOW_SECONDS: string;
  /** How long JWKS fetched from auth-service is cached (seconds). */
  AUTH_JWKS_CACHE_TTL_SECONDS?: string;
}

export interface Variables {
  requestId: string;
  config: GatewayConfig;
  /** User from the signed JWT; null means an unauthenticated request. */
  user: AuthenticatedUser | null;
}

export type AppEnv = {
  Bindings: Bindings;
  Variables: Variables;
};
